.wm i{font-style:normal;font-size:9.5px;color:var(--mut)}
.wm b{font-size:11.5px;font-family:var(--mono)}
.chg-list{display:flex;flex-direction:column;gap:6px}
.chg{display:flex;gap:8px;text-align:left;background:var(--panel-2);border:1px solid var(--line-soft);border-radius:8px;padding:8px;width:100%}
