.chg-diff s{color:var(--mut)}
.chg-diff b{color:var(--mod)}
.chg-reason{font-size:11px;color:var(--mut)}
.chg-links{display:flex;gap:10px;font-size:10.5px;flex-wrap:wrap}
.lnk.up,.lnk.down{color:rgba(227,179,65,.85)}
.hint{font-size:11.5px;color:var(--mut);padding:4px 2px}

