.chain-node.self{border-color:rgba(76,154,255,.6);border-left-color:var(--acc);background:rgba(76,154,255,.06)}
.chain-node.on{box-shadow:0 0 0 1px rgba(227,179,65,.45)}
.cn-win{font-size:9.5px;color:var(--mut)}
.cn-line{font-size:11.5px;font-weight:600}
.cn-reason{font-size:10.5px;color:var(--mut)}
.chain-arrow{color:rgba(227,179,65,.8);font-size:10.5px;padding:3px 0 3px 14px}

/* ---------- 滚动条 / 窄屏 ---------- */
::-webkit-scrollbar{width:9px;height:9px}
::-webkit-scrollbar-thumb{background:#252e3e;border-radius:6px;border:2px solid var(--bg)}
::-webkit-scrollbar-track{background:transparent}

@media (max-width:1120px){
  body{overflow:auto}
  #layout{display:flex;flex-direction:column;height:auto}
  .col{overflow:visible}
  #left,#right{border:0;border-bottom:1px solid var(--line)}
  #right{border-bottom:0;border-top:1px solid var(--line)}
}

